  page.wait_for_function('()=>window.RichTextEditing&&window.RichTextRenderer&&window.EInviteEditorBridge')
  page.evaluate("""()=>{EInviteEditorBridge.transact('Create rich editing fixture',doc=>{const base=structuredClone(doc.objects.title);doc.objects['rich-edit']={...base,layerName:'Rich editing test',left:'8%',top:'15%',width:'80%',height:'260px',zIndex:99,richTextModelVersion:1,richText:{version:1,entities:{},paragraphs:[{id:'p-main',paragraphStyleId:'body',locale:'en',direction:'ltr',overrides:{},list:{type:'none',level:0,start:1,marker:'disc'},tabStops:[],runs:[{id:'r-main',text:'Hello ',locale:'en',marks:{}},{id:'r-kh',text:'ក្ខ',locale:'km',marks:{}}]}]}};doc.objects['rich-edit'].html=RichTextDocumentModel.exportLegacyHtml(doc.objects['rich-edit'].richText);doc.objects['rich-edit'].text=RichTextDocumentModel.exportPlainText(doc.objects['rich-edit'].richText)});EInviteEditorBridge.select(['rich-edit']);window.__rtCommands=[];window.addEventListener('einvite:editor-command',e=>window.__rtCommands.push(e.detail))}""");page.wait_for_timeout(350)
  # Toolbar semantics and controlled root.
  ui=page.evaluate("""()=>{const c=document.querySelector('.object[data-id=rich-edit] .content');return{controlled:c.dataset.richTextControlled,role:c.getAttribute('role'),multi:c.getAttribute('aria-multiline'),tools:!!document.querySelector('[data-rich-text-tools]'),names:[...document.querySelectorAll('[data-rich-text-tools] button')].map(x=>x.getAttribute('aria-label'))}}""")
  assert ui['controlled']=='true' and ui['role']=='textbox' and ui['multi']=='true' and ui['tools'] and {'Underline','Strikethrough','Bulleted list','Numbered list','Create or edit link'}<=set(ui['names']),ui
