  for ch in 'ABC': page.evaluate("ch=>document.querySelector('.object[data-id=rich-edit] .content').dispatchEvent(new InputEvent('beforeinput',{inputType:'insertText',data:ch,bubbles:true,cancelable:true}))",ch)
  page.evaluate("()=>RichTextEditing.flush()");page.wait_for_timeout(250)
